#include <iostream>
#include <memory>

int main() {
  std::unique_ptr<int> ptr1 = std::make_unique<int>(10);
  std::cout << "Value of ptr1: " << *ptr1 << std::endl;
  {
    std::unique_ptr<int> ptr2 = std::move(ptr1);
    std::cout << "Value of ptr2 (after move): " << *ptr2 << std::endl;
  } // ptr2 goes out of scope, resource released
  // ptr1 is now empty and accessing it would be undefined behaviour
  return 0;
}
